mapper.update:
update  contract_pay_relation
set pay_url=#{codeUrl}
where contract_id=#{contractId}

mapper.select:
WITH t AS ( SELECT indebted_name AS name, indebted_id AS id_no, su.avatar, cc.create_time, ROW_NUMBER() OVER (PARTITION BY indebted_id ORDER BY cc.create_time DESC) AS rn FROM custom_contract cc LEFT JOIN system_users su ON su.id_no = cc.indebted_id
cc.deleted = 0
and cc.creditor_id =#{idNo}
union all SELECT creditor_name AS name, creditor_id AS id_no, su.avatar, cc.create_time, ROW_NUMBER() OVER (PARTITION BY creditor_id ORDER BY cc.create_time DESC) AS rn FROM custom_contract cc LEFT JOIN system_users su ON su.id_no = cc.creditor_id
cc.deleted = 0
and cc.indebted_id =#{idNo}
) SELECT distinct name, id_no, avatar FROM t WHERE rn = 1 and id_no!=#{idNo} LIMIT 10;

select model from contract_model


        and app_version=#{appVersion}


order by create_time desc limit 1

select mpu.openid from mp_user mpu left join mini_user mnu on mpu.union_id =mnu.union_id and mpu.deleted =0 and mnu.deleted =0
and mnu.user_id=mnu.creator
and mnu.user_id =#{id}
